export function cardDesigns(){const designs=new Map();for(const card of deck()){const key=JSON.stringify([card.type,card.name,card.action,card.value,card.colors]);if(designs.has(key))designs.get(key).copies++;else designs.set(key,{...card,copies:1});}return [...designs.values()];}
export function cardFacts(card){
 if(card.type==='money')return [`Bank this card as ${card.value}M.`,`Use it to pay from your bank. No change is given.`];
 if(card.type==='property')return [card.colors.length===10?'Choose any property color. This card has no monetary value. Reassign it on your own turn for one play in every difficulty.':card.colors.length>1?'Choose either listed color when playing it. Reassigning its color on your turn costs one play in every difficulty.':'Play this property into its matching color set.',...card.colors.map(color=>`${GROUPS[color].name}: ${GROUPS[color].names.length} cards for a full set. Rent by number owned: ${GROUPS[color].rent.map((value,index)=>`${index+1} → ${value}M`).join('; ')}.`)];
 const facts=[card.description];
 if(card.action==='rent')facts.push(card.colors.length===10?'Choose any color you own and one opponent.':`Charge all opponents for one color you own: ${card.colors.map(color=>GROUPS[color].name).join(' or ')}.`, 'Rent depends on your properties and buildings in the chosen color. Each Double the Rent uses an additional play.');
 if(card.action==='house'||card.action==='hotel')facts.push('Only one house and one hotel per complete street set. Never place on utilities or railroads.');
 if(card.action==='no')facts.push('Use when an action targets you. Another Just Say No can counter your response.');
 facts.push(`Bank this action card for its printed cash value using one play, or play it when eligible, hold it for later, or discard it. Once banked, it is cash only and cannot be used for its action or returned to your hand. Discards cost one play each in Hard. Required excess discards are free in Easy and Normal; voluntary discards cost one play each. Required discards must finish even when no plays remain.`);
 return facts;
}

